I'll create a comprehensive PR review agent for Claude Code that analyzes pull requests and posts structured, actionable feedback.

## PR Review Agent for Claude Code

```javascript
#!/usr/bin/env node

/**
 * PR Review Agent for Claude Code
 * 
 * Analyzes pull requests and posts structured, actionable feedback.
 * 
 * Usage:
 *   node pr-review-agent.js --repo owner/repo --pr 123 [--gh-token YOUR_TOKEN]
 * 
 * Environment variables:
 *   GITHUB_TOKEN - GitHub personal access token
 *   CLAUDE_API_KEY - Anthropic API key (optional, uses Claude Code's built-in if omitted)
 */

const fs = require('fs');
const path = require('path');
const https = require('https');
const { execSync } = require('child_process');

// ─── Configuration ───────────────────────────────────────────────────────────

const GITHUB_TOKEN = process.env.GITHUB_TOKEN || '';
const CLAUDE_API_KEY = process.env.CLAUDE_API_KEY || '';

// Parse command line arguments
const args = process.argv.slice(2);
const repoArg = args.find(a => a.startsWith('--repo=')) || args[args.indexOf('--repo') + 1] || '';
const prArg = args.find(a => a.startsWith('--pr=')) || args[args.indexOf('--pr') + 1] || '';
const tokenArg = args.find(a => a.startsWith('--gh-token=')) || args[args.indexOf('--gh-token') + 1] || '';

const REPO = repoArg || (() => { console.error('Error: --repo is required (e.g., owner/repo)'); process.exit(1); })();
const PR_NUMBER = parseInt(prArg) || (() => { console.error('Error: --pr is required'); process.exit(1); })();
const FINAL_TOKEN = tokenArg || GITHUB_TOKEN;

if (!FINAL_TOKEN) {
  console.error('Error: GitHub token required. Set GITHUB_TOKEN env var or pass --gh-token');
  process.exit(1);
}

// ─── GitHub API Helpers ──────────────────────────────────────────────────────

function githubRequest(endpoint, method = 'GET', body = null) {
  return new Promise((resolve, reject) => {
    const url = new URL(`https://api.github.com${endpoint}`);
    const options = {
      hostname: 'api.github.com',
      path: url.pathname + url.search,
      method,
      headers: {
        'Authorization': `Bearer ${FINAL_TOKEN}`,
        'User-Agent': 'claude-code-pr-review-agent',
        'Accept': 'application/vnd.github.v3+json',
        'Content-Type': 'application/json',
      },
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          const parsed = JSON.parse(data);
          if (res.statusCode >= 400) {
            reject(new Error(`GitHub API error ${res.statusCode}: ${parsed.message || data}`));
          } else {
            resolve(parsed);
          }
        } catch (e) {
          reject(new Error(`Failed to parse response: ${data.slice(0, 200)}`));
        }
      });
    });

    req.on('error', reject);
    if (body) req.write(JSON.stringify(body));
    req.end();
  });
}

// ─── Fetch PR Data ───────────────────────────────────────────────────────────

async function fetchPRData() {
  console.log(`🔍 Fetching PR #${PR_NUMBER} from ${REPO}...`);

  const [pr, files, comments, reviewComments] = await Promise.all([
    githubRequest(`/repos/${REPO}/pulls/${PR_NUMBER}`),
    githubRequest(`/repos/${REPO}/pulls/${PR_NUMBER}/files`),
    githubRequest(`/repos/${REPO}/issues/${PR_NUMBER}/comments`),
    githubRequest(`/repos/${REPO}/pulls/${PR_NUMBER}/comments`),
  ]);

  return { pr, files, comments, reviewComments };
}

// ─── Analyze with Claude ─────────────────────────────────────────────────────

async function analyzeWithClaude(prData) {
  const { pr, files } = prData;

  console.log('🧠 Analyzing PR with Claude...');

  // Build file summaries
  const fileSummaries = files.map(f => ({
    filename: f.filename,
    status: f.status,
    additions: f.additions,
    deletions: f.deletions,
    patch: f.patch ? f.patch.slice(0, 3000) : null, // Truncate for token limits
    changes: f.changes,
  }));

  const prompt = `You are a senior software engineer reviewing a pull request. Provide a structured, actionable review.

PR Title: ${pr.title}
PR Description: ${pr.body || '(no description)'}
Author: ${pr.user.login}
Branch: ${pr.head.ref} → ${pr.base.ref}
Total Files Changed: ${files.length}
Total Changes: +${files.reduce((s, f) => s + f.additions, 0)} / -${files.reduce((s, f) => s + f.deletions, 0)}

## Changed Files
${fileSummaries.map(f => `
### ${f.filename} (${f.status})
+${f.additions} / -${f.deletions}
${f.patch ? `\`\`\`diff\n${f.patch}\n\`\`\`` : '(binary or large file)'}
`).join('\n---\n')}

## Review Guidelines
- Identify potential bugs, security issues, and logic errors
- Check for code quality, readability, and maintainability issues
- Suggest improvements with specific code examples
- Verify adherence to common best practices
- Consider edge cases and error handling
- Check for hardcoded values, magic numbers, or security vulnerabilities

## Output Format
Provide your review as a structured JSON object with this exact format:
{
  "summary": "Overall summary of the PR (2-3 sentences)",
  "score": "1-10 rating (10 = perfect, 1 = needs major rework)",
  "approve": true/false,
  "issues": [
    {
      "severity": "critical" | "major" | "minor" | "suggestion",
      "file": "filename",
      "line": null or line number,
      "title": "Short issue title",
      "description": "Detailed explanation with code examples if applicable",
      "suggestion": "How to fix or improve"
    }
  ],
  "strengths": ["List of positive aspects"],
  "action_items": ["Actionable next steps for the author"]
}`;

  // Use Claude Code's built-in analysis if available, otherwise make API call
  if (CLAUDE_API_KEY) {
    return await callClaudeAPI(prompt);
  } else {
    return await callClaudeCodeCLI(prompt);
  }
}

async function callClaudeAPI(prompt) {
  const response = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': CLAUDE_API_KEY,
      'anthropic-version': '2023-06-01',
    },
    body: JSON.stringify({
      model: 'claude-3-opus-20240229',
      max_tokens: 4000,
      messages: [{ role: 'user', content: prompt }],
    }),
  });

  const data = await response.json();
  const content = data.content?.[0]?.text;

  // Extract JSON from response
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('No JSON found in Claude response');

  return JSON.parse(jsonMatch[0]);
}

async function callClaudeCodeCLI(prompt) {
  try {
    const result = execSync(
      `echo ${JSON.stringify(prompt)} | claude -p "Analyze this PR review context and output ONLY valid JSON matching the specified format:"`,
      { encoding: 'utf-8', maxBuffer: 10 * 1024 * 1024 }
    );

    const jsonMatch = result.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error('No JSON found in Claude CLI response');

    return JSON.parse(jsonMatch[0]);
  } catch (error) {
    console.error('Claude CLI error:', error.message);
    // Fallback to a basic analysis
    return generateBasicReview(prompt);
  }
}

// ─── Fallback Analysis ───────────────────────────────────────────────────────

function generateBasicReview(_prompt) {
  console.log('⚠️ Using fallback analysis...');
  return {
    summary: "Automated review complete. For detailed analysis, ensure Claude API key is configured.",
    score: 5,
    approve: false,
    issues: [],
    strengths: ["PR structure appears standard"],
    action_items: ["Run with CLAUDE_API_KEY for detailed analysis"]
  };
}

// ─── Post Review Comment ─────────────────────────────────────────────────────

async function postReview(prData, reviewResult) {
  console.log('📝 Posting review comment...');

  const { pr } = prData;
  const { summary, score, approve, issues, strengths, action_items } = reviewResult;

  // Build emoji indicators
  const scoreEmoji = score >= 8 ? '🟢' : score >= 5 ? '🟡' : '🔴';
  const approveEmoji = approve ? '✅' : '❌';

  // Build issues section
  const issuesSection = issues.map((issue, i) => {
    const severityEmoji = {
      'critical': '🔴',
      'major': '🟠',
      'minor': '🟡',
      'suggestion': '💡',
    }[issue.severity] || '⚪';

    const fileLine = issue.file ? `**File:** \`${issue.file}\`` + (issue.line ? ` (line ${issue.line})` : '') : '';

    return `${severityEmoji} **${issue.severity.toUpperCase()}:** ${issue.title}
${fileLine}
${issue.description}
${issue.suggestion ? `> **Suggestion:** ${issue.suggestion}` : ''}
`;
  }).join('\n');

  // Build strengths section
  const strengthsSection = strengths.map(s => `- ✅ ${s}`).join('\n');

  // Build action items
  const actionsSection = action_items.map(a => `- [ ] ${a}`).join('\n');

  const commentBody = `## 🤖 Claude Code PR Review

### Summary
${summary}

### Score: ${scoreEmoji} ${score}/10 | **${approveEmoji} ${approve ? 'Approve' : 'Changes Requested'}**

---

### ${issues.length > 0 ? '🔍 Issues Found' : '✅ No Issues Found'}
${issues.length > 0 ? issuesSection : 'No issues detected in this review.'}

---

### 💪 Strengths
${strengthsSection || 'No specific strengths noted.'}

---

### 📋 Action Items
${actionsSection || 'No specific action items.'}

---

<sub>Review generated by Claude Code PR Agent | Score: ${score}/10</sub>`;

  // Post as PR review or issue comment
  const endpoint = `/repos/${REPO}/issues/${PR_NUMBER}/comments`;
  await githubRequest(endpoint, 'POST', { body: commentBody });

  console.log('✅ Review posted successfully!');
  return commentBody;
}

// ─── Main Execution ──────────────────────────────────────────────────────────

async function main() {
  console.log('🚀 Starting PR Review Agent...');
  console.log(`📂 Repository: ${REPO}`);
  console.log(`🔢 PR Number: ${PR_NUMBER}`);

  try {
    // Step 1: Fetch PR data
    const prData = await fetchPRData();
    console.log(`📄 Found ${prData.files.length} changed files`);

    // Step 2: Analyze with Claude
    const reviewResult = await analyzeWithClaude(prData);
    console.log(`📊 Review score: ${reviewResult.score}/10`);

    // Step 3: Post structured review
    const comment = await postReview(prData, reviewResult);

    // Step 4: Output results
    console.log('\n📋 Review Summary:');
    console.log(comment);

    // Exit with appropriate code
    process.exit(reviewResult.approve ? 0 : 1);

  } catch (error) {
    console.error('❌ Error during review:', error.message);
    process.exit(2);
  }
}

main();
```

## Package Configuration

```json
{
  "name": "claude-code-pr-review-agent",
  "version": "1.0.0",
  "description": "AI-powered PR review agent using Claude Code",
  "main": "pr-review-agent.js",
  "bin": {
    "pr-review": "./pr-review-agent.js"
  },
  "scripts": {
    "review": "node pr-review-agent.js",
    "start": "node pr-review-agent.js"
  },
  "keywords": ["claude", "code-review", "pr-review", "github"],
  "license": "MIT"
}
```

## GitHub Actions Workflow

```yaml
# .github/workflows/pr-review.yml
name: Claude Code PR Review

on:
  pull_request:
    types: [opened, synchronize, reopened]

jobs:
  review:
    runs-on: ubuntu-latest
    permissions:
      contents: read
      pull-requests: write
      issues: write

    steps:
      - name: Checkout code
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Install dependencies
        run: npm install

      - name: Run PR Review Agent
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
          CLAUDE_API_KEY: ${{ secrets.CLAUDE_API_KEY }}
        run: |
          node pr-review-agent.js \
            --repo=${{ github.repository }} \
            --pr=${{ github.event.pull_request.number }}
```

## Usage Examples

### Basic Usage
```bash
# Using environment variable
export GITHUB_TOKEN=ghp_xxxxx
export CLAUDE_API_KEY=sk-ant-xxxxx

node pr-review-agent.js --repo=owner/repo --pr=42
```

### With CLI Arguments
```bash
node pr-review-agent.js \
  --repo=owner/repo \
  --pr=42 \
  --gh-token=ghp_xxxxx
```

### Docker Support
```dockerfile
FROM node:20-alpine

WORKDIR /app
COPY package.json pr-review-agent.js ./
RUN npm install

ENTRYPOINT ["node", "pr-review-agent.js"]
```

## Key Features

1. **Structured Review Format**: Issues categorized by severity (critical, major, minor, suggestion)
2. **Actionable Feedback**: Specific code examples and improvement suggestions
3. **Scoring System**: 1-10 rating with clear approval/rejection
4. **GitHub Integration**: Fetches PR data and posts comments automatically
5. **Fallback Analysis**: Works even without Claude API key
6. **Emoji-rich Output**: Visual indicators for quick scanning
7. **Exit Codes**: 0 for approve, 1 for reject, 2 for errors
8. **CI/CD Ready**: GitHub Actions workflow included

The agent provides comprehensive, structured reviews that help developers quickly understand what needs attention and how to fix issues, making code review more efficient and consistent.

