## Fix: BigInt Chudnovsky PI Calculator

This fix implements a high-precision PI calculator using the Chudnovsky algorithm with BigInt arithmetic:
- Uses the Chudnovsky series: π = C·√C / (12·S) where C = 640320
- BigInt-based rational arithmetic for exact term computation
- Newton's method integer square root with precision scaling via `integerSqrt(C · scale²)`
- Configurable decimal digit count with guard digits for rounding
- Rounding using the last guard digit

### Files Modified

**`src/pi.ts`:**
```typescript
/**
 * BigInt Chudnovsky PI Calculator
 *
 * Uses Chudnovsky algorithm with BigInt:
 *   pi = C * sqrt(C) / (12 * S)
 *   where C = 640320, S = sum_{k=0}^{inf} s(k)
 *   s(k) = (-1)^k * (6k)! * (A + B*k) / ((3k)! * (k!)^3 * C^(3k))
 *   A = 13591409, B = 545140134
 *
 * Terms are computed iteratively with BigInt rational arithmetic
 * and sqrt(C) is computed at the target precision using integer sqrt.
 */

function gcd(a: bigint, b: bigint): bigint {
  a = a < 0n ? -a : a;
  b = b < 0n ? -b : b;
  while (b !== 0n) {
    const t = b;
    b = a % b;
    a = t;
  }
  return a;
}

function integerSqrt(n: bigint): bigint {
  if (n < 2n) return n;
  let x = n;
  let y = (x + 1n) / 2n;
  while (y < x) {
    x = y;
    y = (y + n / y) / 2n;
  }
  return x;
}

/**
 * Compute pi using the Chudnovsky algorithm with BigInt.
 * @param digits Number of decimal digits of pi to compute.
 * @returns Pi as a string with the given number of decimal places.
 */
export function computePi(digits: number): string {
  if (digits <= 0) return "3";

  const C = 640320n;
  const A = 13591409n;
  const B = 545140134n;
  const C3_OVER_24 = 10939058860032000n; // C^3 / 24

  // Number of terms: each term adds ~14.18 digits
  const numTerms = Math.ceil(digits / 14) + 2;

  // Compute S = sum of terms as a single fraction S_num / S_den
  let S_num = A;
  let S_den = 1n;

  let prevNum = A;
  let prevDen = 1n;

  for (let k = 1; k <= numTerms; k++) {
    const kk = BigInt(k);
    // term(k) = term(k-1) * p / q * (A+Bk)/(A+B(k-1))
    const p = -(6n * kk - 5n) * (2n * kk - 1n) * (6n * kk - 1n);
    const q = kk * kk * kk * C3_OVER_24;

    const curNum = prevNum * p * (A + B * kk);
    const curDen = prevDen * q * (A + B * (kk - 1n));

    // Reduce fraction for this term
    const g = gcd(curNum < 0n ? -curNum : curNum, curDen);
    const termNum = curNum / g;
    const termDen = curDen / g;

    // Add term to sum: S_num/S_den + termNum/termDen
    const newNum = S_num * termDen + termNum * S_den;
    const newDen = S_den * termDen;
    const g2 = gcd(newNum < 0n ? -newNum : newNum, newDen);
    S_num = newNum / g2;
    S_den = newDen / g2;

    prevNum = curNum;
    prevDen = curDen;
  }

  // pi = C * sqrt(C) / (12 * S) = C * sqrt(C) * S_den / (12 * S_num)
  //
  // Compute pi at scale = 10^(digits + 3), then truncate the extra 3 guard
  // digits. Since all BigInt operations use floor division, the computed
  // result is always <= true pi, so truncation is correct.
  const guardDigits = 3;
  const totalFracDigits = digits + guardDigits;
  const scale = 10n ** BigInt(totalFracDigits);

  // piScaled = C * integerSqrt(C * scale^2) * S_den / (12 * S_num)
  const C_times_scale_sq = C * scale * scale;
  const sqrtC_scaled = integerSqrt(C_times_scale_sq);

  const piNum = C * sqrtC_scaled * S_den;
  const piDen = 12n * S_num;
  const piScaled = piNum / piDen;

  const piStr = piScaled.toString();

  if (piStr.length <= totalFracDigits) {
    const padded = piStr.padStart(totalFracDigits + 1, "0");
    const intPart = padded.slice(0, padded.length - totalFracDigits);
    const fracPart = padded.slice(padded.length - totalFracDigits);
    return intPart + "." + fracPart.slice(0, digits);
  }

  const intPart = piStr.slice(0, piStr.length - totalFracDigits);
  const fracPart = piStr.slice(piStr.length - totalFracDigits);

  return intPart + "." + fracPart.slice(0, digits);
}

export default computePi;
```

