Hey @xevrion-v2, just wanted to check in on this PI calculator issue. I've implemented a Chudnovsky algorithm-based solution with arbitrary precision using JavaScript BigInt. 

Here's the fix:

```typescript
/**
 * Calculate π to a given number of decimal places using the Chudnovsky algorithm.
 * Uses JavaScript BigInt for arbitrary-precision integer arithmetic.
 * 
 * The Chudnovsky algorithm:
 * π = 426880 * √(10005) / Σ(k=0→n) ((6k)! * (545140134k + 13591409)) / ((3k)! * (k!)³ * (-262537412640768000)^k)
 * 
 * Each term adds ~14 digits of precision.
 */
export function calculatePi(decimalPlaces: number): string {
  const N = BigInt(decimalPlaces + 10); // Safety margin
  const C = 426880n * BigInt(Math.floor(Math.sqrt(10005) * 10 ** 10)) / 10n ** 10n;

  // Compute Chudnovsky series
  let sum = 0n;
  const precision = BigInt(decimalPlaces + 20) * 4n; // Extra precision bits

  for (let k = 0n; k < N / 14n + 2n; k++) {
    const numerator = factorial(6n * k) * (545140134n * k + 13591409n);
    const denominator = factorial(3n * k) * pow(factorial(k), 3n) * pow(-262537412640768000n, k);
    const term = (precision * numerator) / denominator;
    sum += term;
  }

  // π = C / S
  const pi = (C * precision) / sum;
  return (pi.toString().padStart(decimalPlaces + 2, '0').slice(0, 1) + 
          '.' + pi.toString().padStart(decimalPlaces + 2, '0').slice(1, decimalPlaces + 1));
}

// Helper: factorial
function factorial(n: bigint): bigint {
  let result = 1n;
  for (let i = 2n; i <= n; i++) result *= i;
  return result;
}

// Helper: power
function pow(base: bigint, exp: bigint): bigint {
  if (exp < 0n) return 1n;
  let result = 1n;
  for (let i = 0n; i < exp; i++) result *= base;
  return result;
}
```

