## Fix: LDAP Injection with Blind Boolean-Based Extraction

**Vulnerability:** Unsanitized LDAP query parameters enable blind boolean-based extraction.

### Fix

```python
import re

class LDAPInjectionPrevention:
    '''Prevent LDAP injection with input sanitization and safe query building.'''

    LDAP_SPECIAL = re.compile(r'[\\*()\\0]')

    @staticmethod
    def escape_ldap(value: str) -> str:
        return LDAPInjectionPrevention.LDAP_SPECIAL.sub(
            lambda m: f'\\{ord(m.group(0)):02x}', value
        )

    @staticmethod
    def validate_username(username: str) -> bool:
        return bool(re.match(r'^[a-zA-Z0-9._@-]+$', username))

    @staticmethod
    def build_auth_filter(username: str) -> str:
        safe = LDAPInjectionPrevention.escape_ldap(username)
        return f'(uid={safe})'

    @staticmethod
    def build_search_filter(attr: str, value: str) -> str:
        if not re.match(r'^[a-zA-Z][a-zA-Z0-9_-]*$', attr):
            raise ValueError('Invalid attribute name')
        safe = LDAPInjectionPrevention.escape_ldap(value)
        return f'(&(objectClass=person)({attr}={safe}))'

